    tags=['m_MT_RSTD_BKGS_MSR_ANNUITY']
) }}
{{ config(materialized='table') }}
-- Self-referencing table(s): 'WI_RSTD_BKGS_MSR_ANNUITY_3_KEY1' used as both source and target in this mapping.
-- Materialized as TABLE to snapshot source data before the target model overwrites it.
SELECT
   BOOKINGS_MEASURE_KEY,
   BKGS_MEASURE_TRANS_TYPE_CODE,
   BOOKINGS_PROCESS_DATE,
   SALES_TERRITORY_KEY,
   SALES_REP_NUMBER,
   CASE
      WHEN ((CAST(CAST(BOOKINGS_PROCESS_DATE AS DATE) - CAST(RU_SERVICE_CONTRACT_START_DTM AS DATE) AS INTEGER) * 12 :: FLOAT) / 365) - (DV_CONTRACT_DURATION - 12) >= 0
         THEN 'ANNUITY31'
      ELSE CASE
         WHEN ANNUITY_MONTH1 <= BOOKINGS_PROCESS_MONTH
            THEN 'ANNUITY321'
         ELSE 'ANNUITY322'
      END
   END ANNUITY_TYPE,
   DV_FMV_FLG,
   ADJUSTMENT_CODE
FROM
   (
      SELECT
         BOOKINGS_MEASURE_KEY,
         BKGS_MEASURE_TRANS_TYPE_CODE,
         BOOKINGS_PROCESS_DATE,
         SALES_TERRITORY_KEY,
         SALES_REP_NUMBER,
         BOOKINGS_PROCESS_MONTH,
         RU_SERVICE_CONTRACT_START_DTM,
         DV_CONTRACT_DURATION,
         MAX(ANNUITY_MONTH) ANNUITY_MONTH1,
         DV_FMV_FLG,
         ADJUSTMENT_CODE
      FROM
         {{ var('m_MT_RSTD_BKGS_MSR_ANNUITY_STGDB') }}.WI_RSTD_BKGS_MSR_ANNUITY_23
      WHERE
         COLLATE(ANNUITY_TYPE, 'en-ci-rtrim') = 'ANNUITY3'
      GROUP BY
         BOOKINGS_MEASURE_KEY,
         BKGS_MEASURE_TRANS_TYPE_CODE,
         BOOKINGS_PROCESS_DATE,
         SALES_TERRITORY_KEY,
         SALES_REP_NUMBER,
         BOOKINGS_PROCESS_MONTH,
         RU_SERVICE_CONTRACT_START_DTM,
         DV_CONTRACT_DURATION,
         DV_FMV_FLG,
         ADJUSTMENT_CODE
   ) ABC